presets.css:
/* ===== 变量（夜间配色 + 你的微调旋钮） ===== */
:root{
  --line-me:#3f8f55;              /* 我的气泡 */
  --line-them:#2c2e33;            /* char 气泡 */
  --line-text:#f0f0f0;            /* 文字、顶栏名字 */
  --line-sub:#bdbdbd;             /* 既読、时间、引用文字（浅灰） */
  --line-icon:#e6e6e6;            /* 顶栏、底栏图标 */
  --line-bar:rgba(20,20,22,.92);  /* 顶栏、底栏背景 */
  --line-input:#2c2e33;           /* 输入框 */
  --top-lift:60px;                /* 顶栏上提 */
  --read-size:8px;                /* 既読字号 */
  --them-down:6px;                /* char 气泡下移 */
  --shift-them:10px;              /* char 靠左 */
  --shift-me:10px;                /* user 靠右 */
}

/* ===== 顶栏 ===== */
.chat-thread-top{
  margin:0 !important;margin-top:calc(var(--top-lift) * -1) !important;
  left:0 !important;right:0 !important;width:100% !important;max-width:none !important;
  padding:env(safe-area-inset-top,0px) 0 0 !important;border-radius:0 !important;
  backdrop-filter:none !important;-webkit-backdrop-filter:none !important;
  background:var(--line-bar) !important;box-sizing:border-box}
.chat-thread-top::before,.chat-thread-top::after,
.chat-thread-pill::before,.chat-thread-pill::after{display:none !important}
.chat-thread-pill{
  margin:0 !important;width:100% !important;max-width:none !important;height:34px !important;
  padding:0 12px !important;border:0;border-radius:0 !important;box-shadow:none !important;
  background:transparent !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;
  filter:none !important;display:flex;align-items:center;box-sizing:border-box}
.chat-back{background:none;border:0;color:var(--line-text) !important}
.chat-back svg,.chat-back svg path{stroke:var(--line-text) !important;stroke-width:2.4}
.chat-thread-center{flex:1;text-align:left;margin-left:-10px !important}
.chat-thread-center h2{font-size:16px !important;font-weight:700;color:var(--line-text) !important;margin:0}
.chat-thread-head-actions{display:flex;align-items:center;gap:6px}
.chat-thread-head-xinsheng,.chat-thread-head-more{width:32px;height:32px;padding:0;border:0;background:none;
  display:flex;align-items:center;justify-content:center}
.chat-thread-head-xinsheng svg,.chat-thread-head-more svg{display:none}
/* 装饰：放大镜 */
.chat-thread-head-actions::before{content:"";width:24px;height:24px;margin-right:6px;background:var(--line-icon) !important;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'><circle cx='11' cy='11' r='7'/><path d='M16.5 16.5L21 21'/></svg>") center/contain no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'><circle cx='11' cy='11' r='7'/><path d='M16.5 16.5L21 21'/></svg>") center/contain no-repeat}
/* 心声：电话形状 */
.chat-thread-head-xinsheng::before{content:"";width:24px;height:24px;background:var(--line-icon) !important;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linejoin='round'><path d='M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2z'/></svg>") center/contain no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linejoin='round'><path d='M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2z'/></svg>") center/contain no-repeat}
/* 对话设置：三横线 */
.chat-thread-head-more::before{content:"";width:24px;height:24px;background:var(--line-icon) !important;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'><path d='M4 7h16M4 12h16M4 17h16'/></svg>") center/contain no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'><path d='M4 7h16M4 12h16M4 17h16'/></svg>") center/contain no-repeat}

/* ===== 日期胶囊 ===== */
.chat-msg-timestamp{display:table;margin:14px auto 8px;padding:2px 12px;border-radius:12px;
  background:rgba(255,255,255,.18) !important;color:var(--line-text) !important;font-size:12px}

/* ===== 消息行 ===== */
.chat-msg{display:flex;align-items:flex-end;gap:8px;padding:0 !important;margin:6px 0}
.chat-msg.is-me{justify-content:flex-end;position:relative !important;left:var(--shift-me) !important}
.chat-msg.is-them{align-items:center !important;position:relative !important;left:calc(var(--shift-them) * -1) !important}
.chat-msg.is-them .chat-ava{align-self:center !important;border-radius:50%}
.chat-msg-name{display:none}
.chat-msg-body{max-width:78%;flex:0 1 auto !important;width:auto !important}
.chat-msg.is-them .chat-msg-body{position:relative !important;top:var(--them-down) !important}
.chat-msg.has-quote .chat-msg-body{max-width:calc(100vw - 64px) !important}
.chat-msg .chat-msg-body .chat-swipe-content{
  display:flex !important;flex-direction:row !important;align-items:flex-end !important;gap:2px !important}

/* ===== 既読 + 时间：user 在气泡左，char 在气泡右 ===== */
.chat-msg .chat-msg-time{
  position:static !important;inset:auto !important;transform:none !important;
  margin:0 !important;padding:0 !important;display:block !important;
  font-size:8px;line-height:1.3;white-space:nowrap;color:var(--line-sub) !important}
.chat-msg.is-me .chat-msg-time{order:-1 !important;text-align:right !important}
.chat-msg.is-them .chat-msg-time{order:2 !important;text-align:left !important}
.chat-msg.is-me .chat-msg-time::before,
.chat-msg.is-them .chat-msg-time::before{
  content:"既読";display:block;font-size:var(--read-size);line-height:1.2;color:var(--line-sub) !important}

/* ===== 气泡 ===== */
.chat-bubble{position:relative;padding:6px 10px;border-radius:20px;font-size:12px;line-height:1.3;
  border:0;box-shadow:none;color:var(--line-text) !important}
.chat-msg.is-me .chat-bubble{background:var(--line-me) !important;margin-left:0 !important}
.chat-msg.is-them .chat-bubble{background:var(--line-them) !important;margin-left:0 !important}
.chat-bubble-primary,.chat-bubble-primary span{margin:0;color:var(--line-text) !important}

/* ===== 引用回复气泡 ===== */
.chat-bubble.has-inner-quote{padding:0 !important;min-width:0 !important;width:62vw !important;max-width:100% !important;flex:0 1 auto}
.chat-qq-quote{display:grid;grid-template-columns:30px 1fr;column-gap:8px;align-items:center;
  width:100%;min-width:0;text-align:left;margin:0;padding:12px 14px 10px;border:0;border-radius:0;
  background:transparent !important;border-bottom:1px solid rgba(255,255,255,.2) !important}
.chat-qq-quote::before{content:"";grid-row:1 / span 2;width:30px;height:30px;border-radius:50%;
  background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.8' stroke-linecap='round'><circle cx='12' cy='8' r='4'/><path d='M4 21c0-4 4-6 8-6s8 2 8 6'/></svg>") center/62% no-repeat,#7aa592}
.chat-qq-quote-name{grid-column:2;font-size:13px;font-weight:700;color:var(--line-text) !important}
.chat-qq-quote-text{grid-column:2;font-size:13px;color:var(--line-sub) !important;display:-webkit-box;
  -webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;word-break:break-all}
.has-inner-quote .chat-bubble-primary{padding:12px 14px}

/* ===== 底栏：+ / 装饰相机 / 装饰相册 / Aa输入框 / 语音 ===== */
.chat-compose{padding:6px 10px calc(env(safe-area-inset-bottom,0px) + 6px);background:var(--line-bar) !important;
  backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}
.chat-compose-field,.chat-compose-bar{display:flex;align-items:center;gap:4px;padding:0;border:0;border-radius:0;box-shadow:none;background:none}
.chat-compose-plus-wrap{order:1}
.chat-compose-plus{width:36px;height:36px;padding:0;border:0;background:none;color:var(--line-icon) !important}
.chat-compose-plus svg,.chat-compose-plus svg path{width:26px;height:26px;stroke:var(--line-icon) !important;stroke-width:2}
/* 装饰：相机 */
.chat-compose-bar::before{content:"";order:2;width:36px;height:36px;background:var(--line-icon) !important;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linejoin='round'><path d='M4 8h3l1.5-2h7L17 8h3v11H4z'/><circle cx='12' cy='13.5' r='3.5'/></svg>") center/26px no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linejoin='round'><path d='M4 8h3l1.5-2h7L17 8h3v11H4z'/><circle cx='12' cy='13.5' r='3.5'/></svg>") center/26px no-repeat}
/* 装饰：相册 */
.chat-compose-bar::after{content:"";order:3;width:36px;height:36px;background:var(--line-icon) !important;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linejoin='round' stroke-linecap='round'><rect x='4' y='5' width='16' height='14' rx='2'/><path d='M4 16l5-5 4 4 3-3 4 4'/></svg>") center/26px no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linejoin='round' stroke-linecap='round'><rect x='4' y='5' width='16' height='14' rx='2'/><path d='M4 16l5-5 4 4 3-3 4 4'/></svg>") center/26px no-repeat}
/* 输入框 */
.chat-compose-input{order:4;flex:1;min-height:36px;border:0;border-radius:20px;padding:7px 40px 7px 14px;
  color:var(--line-text) !important;font-size:16px;
  background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23999' stroke-width='1.6' stroke-linecap='round'><circle cx='12' cy='12' r='9'/><path d='M8 14c1 1.5 2.5 2 4 2s3-.5 4-2M9 10h.01M15 10h.01'/></svg>") right 10px center/22px no-repeat,var(--line-input) !important}
.chat-compose-input:placeholder-shown{
  background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23999' stroke-width='1.6' stroke-linecap='round'><circle cx='12' cy='12' r='9'/><path d='M8 14c1 1.5 2.5 2 4 2s3-.5 4-2M9 10h.01M15 10h.01'/></svg>") right 10px center/22px no-repeat,
  url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='30' height='20'><text x='0' y='16' font-size='17' fill='%23999' font-family='sans-serif'>Aa</text></svg>") left 14px center/auto 20px no-repeat,var(--line-input) !important}
.chat-compose-input::placeholder{color:transparent}
/* 语音：麦克风 */
.chat-compose-icon.is-voice{order:5;width:36px;height:36px;padding:0;border:0;background:none;display:flex;align-items:center;justify-content:center}
.chat-compose-icon.is-voice svg{display:none}
.chat-compose-icon.is-voice::before{content:"";width:26px;height:26px;background:var(--line-icon) !important;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.9' stroke-linecap='round'><rect x='9' y='3' width='6' height='11' rx='3'/><path d='M5 11a7 7 0 0 0 14 0M12 18v3'/></svg>") center/contain no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.9' stroke-linecap='round'><rect x='9' y='3' width='6' height='11' rx='3'/><path d='M5 11a7 7 0 0 0 14 0M12 18v3'/></svg>") center/contain no-repeat}
/* 发送键/回复键隐藏；输入文字后才显示发送键 */
.chat-compose-icon.is-reply,.chat-compose-icon.is-send{display:none}
.chat-compose-bar:has(.chat-compose-input:not(:placeholder-shown)) .chat-compose-icon.is-send{display:flex;order:6}
.chat-compose-bar:has(.chat-compose-input:not(:placeholder-shown)) .chat-compose-icon.is-voice{display:none}
